BEGIN;
CREATE TABLE payment.payout_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES identity.users(id), wallet_id uuid NOT NULL REFERENCES ledger.wallets(id), amount numeric(20,8) NOT NULL CHECK(amount>0), currency char(3) NOT NULL, status payment.payout_status NOT NULL DEFAULT 'REQUESTED', idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE payment.payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, request_id uuid NOT NULL UNIQUE REFERENCES payment.payout_requests(id), provider_id uuid REFERENCES core.providers(id), external_id text, status payment.payout_status NOT NULL DEFAULT 'APPROVED', ledger_transaction_id uuid REFERENCES ledger.transactions(id), processed_at timestamptz, UNIQUE(provider_id,external_id));
CREATE TABLE payment.settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, provider_id uuid NOT NULL REFERENCES core.providers(id), external_id text NOT NULL, currency char(3) NOT NULL, gross numeric(20,8) NOT NULL, fees numeric(20,8) NOT NULL DEFAULT 0, net numeric(20,8) NOT NULL, settled_at timestamptz NOT NULL, UNIQUE(provider_id,external_id));
CREATE TABLE payment.reconciliations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, settlement_id uuid NOT NULL REFERENCES payment.settlements(id), status text NOT NULL, differences jsonb NOT NULL DEFAULT '{}'::jsonb, reconciled_at timestamptz);
COMMIT;
